/* selectMenuNm - Lee JiSeob */
SELECT
X.MENU_NO,
X.MENU_NM,
(SELECT F.MENU_NM FROM SAB200 F /* 메뉴 */ WHERE F.MENU_LEVELA_NO = 1 START WITH F.MENU_NO = X.MENU_NO CONNECT BY PRIOR F.UP_MENU_NO = F.MENU_NO) AS ROOT_MENU_NM
FROM (
SELECT D.MENU_NM, D.MENU_NO FROM SAB200 D /* 메뉴 */, SAB100 E /* 프로그램 */ WHERE D.PROGRM_ID = E.PROGRM_ID AND E.URL_ADDR = #{menuUrl}
) X

